    }
  }
}

// Only the receipt's own verdict is ignored. A GitHub failure other than a missing object (outage, rate limit, permission) is
// something CI itself could not do and keeps its ordinary classification.
const rejection = error => error instanceof ReceiptRejected ? error.reason : error instanceof ChunkedRecordError ? 'record' : null;
const detailOf = error => error instanceof ReceiptRejected ? error.detail : {};

// The one decision for a claimed receipt: `ref` is set only when it verifies in every respect. Any other outcome returns
// the fixed class in `rejected` (or neither, when no receipt is claimed) and the receipt is never consulted again.
async function screenReceipt({github, repo, pr, engine, trust, configDigest, policyDigest, reviewerDigest, humanReview = false}) {
  let ref;
  try {ref = marker(pr.body);} catch (error) {return {ref: null, rejected: error.reason, detail: error.detail};}
  if (!ref) return {ref: null, rejected: null};
  let bundle;
  try {bundle = await loadReceipt({github, repo, ref, trust});} catch (error) {
    const reason = rejection(error) ?? (error.status === 404 ? 'unavailable' : null);
    if (!reason) throw error;
    return {ref: null, rejected: reason, detail: detailOf(error)};
  }
  try {
    const verified = verifyReceipt(bundle, {engine, trust, repository: `${repo.owner}/${repo.repo}`, author: pr.user.login, pullNumber: pr.number,
      headSha: pr.head.sha, baseSha: pr.base.sha, configDigest, policyDigest, reviewerDigest, humanReview});
    return {ref, bundle, verified, rejected: null};
  } catch (error) {return {ref: null, rejected: rejection(error) ?? 'malformed', detail: detailOf(error)};}
}

// The same decision for the live repository: the signed sources, inventory and patches must equal what GitHub reports.
async function screenSources(options) {
  try {
    await verifySources(options);
    return null;
  } catch (error) {
    const reason = rejection(error) ?? (error.status === 404 ? 'source' : null);
    if (!reason) throw error;
    // A patch mismatch names its file to the caller, but only a file the pull request itself changed: the path
    // otherwise comes from the receipt, which is untrusted text.
    if (error.code === 'RECEIPT_PATCH_MISMATCH' && options.files.some(file => file.filename === error.path)) options.note?.(error.path);
    // A repository contract that changed on the live base names its file. verifySources sets `detail.file` only there, and only
    // to a path the protected configuration names (readme, repository_policy), so it is never receipt text.
    if (error instanceof ReceiptRejected && error.detail?.file !== undefined) options.note?.(error.detail.file);
    return reason;
  }
}

module.exports = {signable, screenReceipt, screenSources, DOMAIN, MAX_RECEIPT_BYTES, validateTrust, validateAttest, attestable, AUTHOR, reviewDecision, issueReceipt, verifySignedRecord, verifyReceipt, marker, loadReceipt, verifySources};

'use strict';

const {digest, impactOf, FACTORS, RULES} = require('./acceptance.cjs');

const MARKER = '<!-- clouseau-acceptance:v2 -->';
const STATE = /<!-- clouseau-state:([A-Za-z0-9+/=]+) -->/;

function clean(value) {
  return String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('|', '&#124;').replaceAll('`', '&#96;').replaceAll('@', '').replace(/[\r\n]+/g, ' ');
}

function score(value) {
  return value.toFixed(2);
}

function priorState(comments, repository, number) {
  const comment = [...comments].reverse().find(item => item.user?.login === 'github-actions[bot]' && item.body.includes(MARKER));
  if (!comment) return {comment: null, findings: []};
  const encoded = comment.body.match(STATE);
  if (!encoded || encoded[1].length > 60000) throw new Error('The previous acceptance ledger is incomplete');
  const value = JSON.parse(Buffer.from(encoded[1], 'base64').toString('utf8'));
  if (value.version !== 2 || value.repository !== repository || value.number !== number ||
      !/^[a-f0-9]{40}$/.test(value.head_sha) || !Array.isArray(value.findings) ||
      value.findings.some(item => !/^[a-f0-9]{64}$/.test(item.id) || typeof item.blocking !== 'boolean' ||
        !['confirmed', 'investigating', 'outstanding', 'corrected', 'dismissed', 'advisory_closed'].includes(item.state) ||
        !item.title || !item.path || !item.cause || !item.obligation)) {
    throw new Error('The previous acceptance ledger failed identity validation');
  }
  return {comment: comment.id, findings: value.findings};
}

function reconcile(result, snapshot, previous = []) {
  const records = new Map();
  const previousById = new Map(previous.map(item => [item.id, item]));
