    repair_required: ['Repair required', 'The implementation agent fixes the findings and runs verification and review again.'],
    blocked_integrity: ['Test integrity repair required', 'Repair the test or evidence problem before requesting approval.'],
    review_incomplete: ['Review incomplete', 'Investigate the missing or uncertain evidence before requesting approval.'],
    owner_decision: ['Owner decision required', 'The owner decides the purpose or authority question; all technical checks remain mandatory.'],
  };
  const [title, next] = decisions[result.decision];
  const lines = [MARKER, `## Clouseau — ${title}`];
  if (new Set(result.reviews.map(review => review.scores.decision)).size > 1) {
    lines.push('', '**Reviewer disagreement:** ' + result.reviews.map(review => `${clean(review.role)}: ${decisions[review.scores.decision][0]}`).join('; ') + '.');
  }
  for (const hold of new Set(result.reviews.map(review => review.scores.hold).filter(Boolean))) lines.push('', `**Approval held:** ${clean(hold)}.`);
  if (result.decision === 'owner_decision') lines.push('', '**Owner decision:** Confirm this exact revision’s changes to protected review controls.');
  const findings = new Map();
  for (const review of result.reviews) for (const [index, finding] of review.report.findings.entries()) {
    const identity = digest([finding.path, finding.cause.trim().toLowerCase().replace(/\s+/g, ' '),
      finding.obligation.trim().toLowerCase().replace(/\s+/g, ' ')]);
    const entry = review.scores.findings[index];
    const best = findings.get(identity);
    if (!best || entry.score > best.entry.score) findings.set(identity, {finding, entry, report: review.report});
  }
  if (!findings.size) {
    const summary = Array.from(clean(result.reviews[0].report.summary));
    lines.push('', summary.slice(0, 240).join('') + (summary.length > 240 ? '…' : ''), '', '**Technical findings:** None.');
  } else {
    const rows = [...findings.values()].sort((a, b) => b.entry.score - a.entry.score);
    const blocking = rows.filter(({entry}) => entry.score >= RULES.defect_threshold).length;
    lines.push('', `**${rows.length} ${rows.length === 1 ? 'finding' : 'findings'}** · **${blocking} blocking** (score ${RULES.defect_threshold} or above) · highest **${Math.round(rows[0].entry.score)}/100**`, '',
      '| Finding | Need | Conf | Sev | Active | Impact | Score |', '|---|---:|---:|---:|---:|---:|---:|');
    for (const {finding, entry} of rows) {
      const value = name => score(finding.factors[name].value);
      lines.push(`| ${clean(finding.title)}${entry.score >= RULES.defect_threshold ? '' : ' *(optional)*'} | ${value('necessity')} | ${value('confidence')} | ${value('severity')} | ${value('activation')} | ×${impactOf(finding).toFixed(2)} | **${Math.round(entry.score)}** |`);
    }
    lines.push('', `Score = 100 × Conf × the larger of Need or (Active × Sev × Impact), capped at 100. ${RULES.defect_threshold} or above blocks approval.`, '', '**TL;DR**');
    const sentence = text => { const first = clean(text).match(/^.*?[.!?](?=\s|$)/)?.[0] || clean(text); return Array.from(first).length > 200 ? Array.from(first).slice(0, 199).join('') + '…' : first; };
    for (const {finding, entry, report} of rows) {
      const citation = report.evidence.find(item => item.id === finding.evidence[0]);
      const source = snapshot.sources[citation.source];
      const evidence = /^[a-f0-9]{40}$/.test(source.ref) && ['source', 'contract'].includes(source.kind)
        ? `[${clean(source.path)}:${citation.start}](https://github.com/${snapshot.repository}/blob/${source.ref}/${source.path.split('/').map(encodeURIComponent).join('/')}#L${citation.start}-L${citation.end})`
        : clean(citation.id);
      lines.push(`- **${clean(finding.title)}** (${evidence}): ${sentence(finding.consequence)} **Fix:** ${sentence(finding.obligation)}${entry.score >= RULES.defect_threshold ? '' : ' Optional.'}`);
    }
  }
  const gates = new Map();
  for (const review of result.reviews) for (const gate of review.report.gates) {
    if (['satisfied', 'inapplicable'].includes(gate.state) || gates.has(gate.name)) continue;
    gates.set(gate.name, `**Check requiring attention — ${clean(gate.name.replaceAll('_', ' '))}:** ${clean(gate.reason)}`);
  }
  for (const gate of gates.values()) lines.push('', gate);
  if (state.unresolved.length) {
    lines.push('', '**Outstanding prior blockers:** ' + state.findings.filter(finding => state.unresolved.includes(finding.id))
      .map(finding => `${clean(finding.title)} (${clean(finding.path)})`).join('; ') + '.');
  }
  lines.push('', `**Next action:** ${next}`, '', `Reviewed revision: \`${snapshot.head_sha.slice(0, 7)}\`. CI, merge and deployment are reported separately.`);
  return lines;
}

function render(result, snapshot, state, {compact = false, unbounded = false} = {}) {
  const sources = new Map();
  for (const review of result.reviews) for (const evidence of review.report.evidence) {
    if (!sources.has(evidence.source)) sources.set(evidence.source, {id: `S${sources.size + 1}`, lines: new Set()});
    const source = sources.get(evidence.source);
    for (let line = evidence.start; line <= evidence.end; line++) source.lines.add(line);
  }
  const lines = overview(result, snapshot, state);
  if (!compact) lines.push('', '<details><summary>Scoring and evidence</summary>', '',
    `Revision: \`${snapshot.head_sha}\` · Policy: \`${snapshot.policy_digest}\``, '',
    `A technical finding scoring ${RULES.defect_threshold} or above blocks approval. Display rounding never decides eligibility.`, '');
  if (!compact) lines.push('Technical Q = 100 × confidence × min(1, max(necessity, activation × severity × (1 + .25 irreversibility + .20 reach + .20 detection + .20 propagation + .15 recurrence))). xG affects optional priority only; it never creates a blocker.', '');
  if (!compact) for (const review of result.reviews) {
    lines.push(`### ${clean(review.role)}`, '', clean(review.report.summary), '',
      '| Finding | Score | BR | xG | Optional priority | Disposition |', '|---|---:|---:|---:|---:|---|');
    for (const [index, finding] of review.report.findings.entries()) {
      const value = review.scores.findings[index];
      lines.push(`| ${clean(finding.title)} | ${score(value.score)} | ${finding.blast_radius} | ${value.xg} | ${value.priority.toFixed(2)} | ${value.disposition} |`);
    }
    if (!review.report.findings.length) lines.push('| No admitted technical findings | — | — | — | — | — |');
    lines.push('', '| Gate | State | Evidence |', '|---|---|---|');
    for (const gate of review.report.gates) lines.push(`| ${gate.name} | ${gate.state} | ${clean(gate.reason)} |`);
    for (const finding of review.report.findings) {
      lines.push('', `<details><summary>Inputs: ${clean(finding.title)}</summary>`, '',
        `Cause: ${clean(finding.cause)} · Trigger: ${clean(finding.trigger)} · Consequence: ${clean(finding.consequence)}`, '',
        '| Factor | Value | Reason | Citations |', '|---|---:|---|---|');
      for (const name of FACTORS.defect) {
        const factor = finding.factors[name];
        lines.push(`| ${name} | ${score(factor.value)} | ${clean(factor.reason)} | ${clean(factor.evidence.join(', '))} |`);
      }
      lines.push('', '</details>');
    }
    lines.push('', '<details><summary>Immutable evidence register</summary>', '', '| Id | Source | Lines |', '|---|---|---|');
    for (const evidence of review.report.evidence) lines.push(`| ${clean(evidence.id)} | ${sources.get(evidence.source).id} | ${evidence.start}–${evidence.end} |`);
    lines.push('', '</details>');
    for (const resolution of review.report.resolutions) lines.push('', `Disposition ${clean(resolution.id)}: **${resolution.state}** — ${clean(resolution.reason)} (${clean(resolution.evidence.join(', '))})`);
  }
  if (!compact && state.findings.length) {
    lines.push('', '| Persistent finding | State | Blocking | Path |', '|---|---|---|---|');
    for (const finding of state.findings) {
      lines.push(`| ${clean(finding.title)} (${finding.id}) | ${finding.state} | ${finding.blocking} | ${clean(finding.path)} |`);
      for (const event of finding.events || []) lines.push('', `History ${finding.id}: ${clean(event.head_sha)} — **${clean(event.state)}** — ${clean(event.reason)}`);
    }
  }
  if (state.unresolved.length) lines.push('', `Outstanding prior blockers: ${state.unresolved.join(', ')}. Absence from a new review is not a resolution.`);
  if (!compact) lines.push('', '</details>');
  const value = {version: 2, repository: snapshot.repository, number: snapshot.number, head_sha: snapshot.head_sha, findings: state.findings};
  lines.push('', `<!-- clouseau-state:${Buffer.from(JSON.stringify(value)).toString('base64')} -->`);
  const body = lines.join('\n');
  if (body.length > 64000 && !unbounded) throw new Error('Complete acceptance ledger exceeds the comment budget; retain it as an artifact and require investigation');
  return body;
}

function publication(result, snapshot, state) {
  const full = render(result, snapshot, state, {unbounded: true});
  if (full.length <= 64000) return {body: full, pages: []};
  const identity = digest(full);
  const content = full.replace(MARKER, '').replace(STATE, '');
  const chunks = [];
  for (let start = 0; start < content.length;) {
    let end = Math.min(start + 50000, content.length);
    if (end < content.length && /[\uD800-\uDBFF][\uDC00-\uDFFF]/.test(content.slice(end - 1, end + 1))) end--;
    chunks.push(content.slice(start, end)); start = end;
  }
  const pages = chunks.map((chunk, index) =>
    `<!-- clouseau-evidence:v2 ${snapshot.head_sha} ${identity} ${index + 1} -->\n` +
    `### Acceptance evidence ${index + 1}/${chunks.length}\nRevision: ${snapshot.head_sha} · Ledger: ${identity}\n\n${chunk}`);
  const body = render(result, snapshot, state, {compact: true});
  return {body, pages};
}

module.exports = {MARKER, clean, score, priorState, reconcile, render, publication};

'use strict';
// A local receipt meeting, on a later run, the acceptance ledger the gate published from that same receipt. Kept apart
// from acceptance-controller.test.cjs so a change here does not resend that file as review evidence.

const {test} = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {createPolicy} = require('./policy.cjs');
const {modelTemplate} = require('./acceptance-review.cjs');
const {digest, FACTORS} = require('./acceptance.cjs');
const {MARKER, reconcile, publication} = require('./acceptance-ledger.cjs');
const {issueReceipt, reviewDecision} = require('./local-receipt.cjs');
const {refresh} = require('./acceptance-sources.cjs');
const {CASES, prepareCase} = require('../test/acceptance-cases.cjs');
const {hostedFiles} = require('../test/hosted-files.cjs');

const config = {...require('../test/fixtures/config.json'), version: 2, repository_policy: '.github/clouseau.md', readme: 'README.md', acceptance: {
  examiner: 'deepseek-flash', challenger: 'deepseek-flash', grader: 'deepseek', grading_model: 'deepseek-flash', repair_attempts: 2,
}};
const STATE = /<!-- clouseau-state:([A-Za-z0-9+/=]+) -->/;
const stateOf = body => JSON.parse(Buffer.from(body.match(STATE)[1], 'base64').toString('utf8'));
const withState = (body, mutate) => {
  const value = stateOf(body); mutate(value);
  return body.replace(STATE, `<!-- clouseau-state:${Buffer.from(JSON.stringify(value)).toString('base64')} -->`);
};
const bot = (id, body) => ({id, user: {login: 'github-actions[bot]', type: 'Bot'}, body});
const FOREIGN = {id: 'f'.repeat(64), kind: 'technical', blocking: false, state: 'advisory_closed', title: 'Another review finding',
  path: 'src/upload.test.js', cause: 'A finding this receipt never made.', obligation: 'Keep the history the receipt signed.'};

// The hosted case of acceptance-controller.test.cjs: one pull request, its files, verification and a scripted provider.
async function fixture(run) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-acceptance-'));
  const old = process.env.DEEPSEEK_API_KEY; process.env.DEEPSEEK_API_KEY = 'fictional';
  try {
    const {github, repo, snapshot} = await prepareCase(CASES[0]);
    const context = {repo, runId: 7, eventName: 'pull_request_target', payload: {pull_request: {number: 3}}};
    const state = {comments: [], reviews: [], writes: [], failed: false, calls: 0,
      pr: {number: 3, node_id: 'PR_3', state: 'open', draft: false, changed_files: 1, user: {login: 'contributor', type: 'User'},
        head: {sha: snapshot.head_sha, ref: 'fix/upload', repo: {id: 7, owner: {login: repo.owner}, name: repo.repo}},
        base: {sha: snapshot.base_sha, ref: 'main'}, auto_merge: {enabled_by: {login: 'github-actions[bot]'}}}};
    const graphql = github.graphql;
    github.graphql = async (query, args) => {
      if (query.startsWith('mutation')) {const disable = query.includes('disablePullRequestAutoMerge'); state.writes.push({name: disable ? 'disable-auto' : 'enable-auto'}); state.pr.auto_merge = disable ? null : {}; return {};}
      return graphql(query, args);
    };
    const endpoint = (name, fn) => Object.assign(fn, {endpointName: name});
    const write = name => endpoint(name, async args => {state.writes.push({name, args}); return {data: {id: 100 + state.writes.length}};});
    github.rest.pulls = {
      get: async () => ({data: structuredClone(state.pr)}),
      listFiles: endpoint('files', async () => ({data: hostedFiles(snapshot)})),
      listReviews: endpoint('reviews', async () => ({data: state.reviews})),
      createReview: write('approve'), requestReviewers: write('request-review'),
    };
    github.rest.issues = {
      listComments: endpoint('comments', async () => ({data: state.comments})),
      createComment: write('create-ledger'), updateComment: write('update-ledger'), addAssignees: write('assign'),
    };
    github.rest.actions = {
      listWorkflowRuns: async () => ({data: {workflow_runs: [{id: 9, run_attempt: 1, head_sha: state.pr.head.sha,
        event: 'pull_request', pull_requests: [{number: 3}], status: 'completed',
        conclusion: state.failed ? 'failure' : 'success', html_url: 'https://github.com/example/gateway/actions/runs/9'}]}}),
      listJobsForWorkflowRun: endpoint('jobs', async () => ({data: [{id: 10, name: 'verify', conclusion: 'success',
        steps: config.verification.steps.map(name => ({name, conclusion: 'success'}))}]})),
    };
    const readContent = github.rest.repos.getContent;
    github.rest.repos.getContent = args => args.path === '.github/CODEOWNERS' ? Promise.resolve({data: {
      encoding: 'base64', content: Buffer.from('* @contributor').toString('base64'), size: 14}}) : readContent(args);
    Object.assign(github.rest.repos, {
      get: async () => ({data: {allow_auto_merge: true}}), getBranch: async () => ({data: {protected: true}}),
      // The owner who comments `/approve-intent` holds maintainer permission.
      getCollaboratorPermissionLevel: async () => ({data: {permission: 'maintain'}}),
    });
    github.paginate = async (method, args) => (await method(args)).data;
    github.request = async () => ({data: [
      {type: 'required_status_checks', parameters: {strict_required_status_checks_policy: true,
        required_status_checks: ['verify', 'approve-and-merge'].map(context => ({context, integration_id: 15368}))}},
      {type: 'pull_request', parameters: {required_approving_review_count: 1, dismiss_stale_reviews_on_push: true, require_last_push_approval: true}},
      {type: 'non_fast_forward'}, {type: 'deletion'},
    ]});
    const core = {info() {}, summary: {addRaw() {return this;}, async write() {}}};
    const recordPath = path.join(directory, 'record.json');
    const fetchImpl = async (_, options) => {
      state.calls++;
      const body = JSON.parse(options.body);
      if (!body.tools) {
        const {questions} = JSON.parse(body.messages[1].content);
        return {ok: true, json: async () => ({choices: [{finish_reason: 'stop', message: {content: JSON.stringify({answers:
          Object.fromEntries(Object.keys(questions).map(id => [id, id.includes('_excess_') ? 'level0' : 'level4']))})}}]})};
      }
